def test_bug1_single_cursor_argument():
    """Test that bind_expr should accept single cursor arguments."""
    print("=== Testing Bug 1: Single Cursor Argument ===")

    @proc
    def bar(n: size, x: f32[n], y: f32[n], z: f32[n]):
        for i in seq(0, n):
            x[i] = y[i]
            x[i] = z[i]

    yi_cursor = bar.find("y[_]")
    zi_cursor = bar.find("z[_]")

    print("Testing with list (should work):")
    try:
        bar_result = bind_expr(bar, [yi_cursor], "y_read")
        print("SUCCESS: bind_expr with list worked")
        print(str(bar_result))
    except Exception as e:
        print(f"ERROR with list: {e}")

    print("\nTesting with single cursor (currently fails):")
    try:
        bar_result2 = bind_expr(bar, zi_cursor, "z_read")
        print("SUCCESS: bind_expr with single cursor worked")
        print(str(bar_result2))
    except Exception as e:
        print(f"ERROR with single cursor: {e}")

def test_bug2_multiple_cursors_cse_behavior():
    """Test that multiple cursors should bind all by default."""
    print("\n=== Testing Bug 2: Multiple Cursors CSE Behavior ===")

    @proc
    def bar(n: size, x: f32[n], y: f32[n], z: f32[n]):
        for i in seq(0, n):
            x[i] = y[i]
            z[i] = y[i]

    yi_cursors = bar.find("y[_]", many=True)
    print(f"Found {len(yi_cursors)} cursors")

    print("Without cse=True (should bind ALL cursors but currently only binds first):")
    try:
        result1 = bind_expr(bar, yi_cursors, "y_read")
        print("Result:")
        print(str(result1))
    except Exception as e:
        print(f"ERROR: {e}")

    print("\nWith cse=True (should bind ALL cursors):")
    try:
        result2 = bind_expr(bar, yi_cursors, "y_read", cse=True)
        print("Result:")
        print(str(result2))
    except Exception as e:
        print(f"ERROR: {e}")

def test_bug3_type_preservation():
    """Test that bind_expr should preserve original expression type."""
    print("\n=== Testing Bug 3: Type Preservation ===")

    @proc 
    def bar(n: size, x: f32[n], y: f32[n]):
        for i in seq(0, n):
            x[i] = y[i] + 1.0

    y_expr_cursors = bar.find("y[_]", many=True)
    print(f"Found {len(y_expr_cursors)} y[_] expressions")

    print("Current behavior - check if type is preserved:")
    try:
        result = bind_expr(bar, y_expr_cursors, "y_read")
        print("Result:")
        print(str(result))

        # Look for the type of the new allocation
        result_str = str(result)
        if "y_read: R" in result_str:
            print("BUG CONFIRMED: Type is hardcoded to R instead of f32")
        else:
            print("Type seems to be preserved correctly")

    except Exception as e:
        print(f"ERROR: {e}")

if __name__ == "__main__":
    test_bug1_single_cursor_argument()
    test_bug2_multiple_cursors_cse_behavior()
    test_bug3_type_preservation()"}

